{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (sentiment ≤ 0.25) and historical prices show downward momentum.",
    "Reduce forecast overshoot after sharp price spikes by applying a 1-2 day lag correction to prevent overreaction.",
    "Apply mean reversion bias: if forecast deviates > ±10% from 30-day moving average, adjust toward historical mean over last 15 days.",
    "Increase forecast sensitivity to recent sentiment shifts: if sentiment rises above 0.5, adjust forecast upward by 2-5% for next 3 days.",
    "For long-term (30-day) forecasts, reduce volatility by smoothing with 7-day exponential moving average if price range exceeds 5% of mean.",
    "When true outcome is significantly lower than forecast (e.g., >15% underperformance), reduce next period’s forecast by 5-10% to account for lagged market correction."
  ]
}
